import{_ as a,o as t,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Interactive widgets","description":"Universal, radial slider and Inventwo comparison from Studio 0.1.295.","frontmatter":{"title":"Interactive widgets","description":"Universal, radial slider and Inventwo comparison from Studio 0.1.295."},"headers":[],"relativePath":"en/projects/grafik-visual-studio/interaktiv.md","filePath":"en/projects/grafik-visual-studio/interaktiv.md","lastUpdated":1792861021000}'),o={name:"en/projects/grafik-visual-studio/interaktiv.md"};function n(s,e,d,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="interactive-widgets" tabindex="-1">Interactive widgets <a class="header-anchor" href="#interactive-widgets" aria-label="Permalink to &quot;Interactive widgets&quot;">​</a></h1><p><strong>Studio 0.1.295</strong> adds the main functional groups from the <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/inventwo-interactive-audit-2026-10-12.md" target="_blank" rel="noreferrer">Inventwo VIS-2 review</a>. <a href="/projects/grafik-visual-studio/interaktiv">Deutsch</a> · <a href="/fr/projects/grafik-visual-studio/interaktiv">Français</a>.</p><h2 id="universal" tabindex="-1">Universal <a class="header-anchor" href="#universal" aria-label="Permalink to &quot;Universal&quot;">​</a></h2><p>In addition to switching and the existing state cycle, choose fixed button values, hold values restoring the previous state, bounded increase/decrease, Studio page navigation, configurable page dialogs or HTTP requests. Legacy buttons keep cycling unless a new option is explicitly selected. Existing property groups and settings are retained.</p><p>Default/individual state content now also includes <strong>Embedded view</strong>, <strong>Color picker</strong> and <strong>Analog clock</strong>. Views support fit-to-size and recursion protection. Color box/wheel, HSV/RGB sliders and optional alpha/Kelvin are available. HEX, HEX8, RGB, HSL, HSV and CIE xy can go to text helpers; HA lights receive validated RGB/Kelvin commands. Alpha applies to HEX8, not HA RGB. The clock uses browser time with optional numbers/seconds and configurable colors.</p><p><strong>Interactive language</strong> selects DE/EN/FR for Universal and radial sliders independently of the shell. User text, entity/page names and technical values are preserved.</p><h2 id="radial-slider-and-previews" tabindex="-1">Radial slider and previews <a class="header-anchor" href="#radial-slider-and-previews" aria-label="Permalink to &quot;Radial slider and previews&quot;">​</a></h2><p>Track, active track and thumb support CSS colors or <code>linear-gradient(90deg, red, rgb(255,200,0) 50%, green)</code>, with percentage stops and directions such as <code>to top</code>. Style inheritance and existing solid colors remain valid.</p><p>Interactive previews fill their frames since 0.1.294. From 0.1.295 Material Design icons and their symbol area are also larger in the sidebar/selector. Only the Studio update is required.</p><h2 id="behavior-and-limits" tabindex="-1">Behavior and limits <a class="header-anchor" href="#behavior-and-limits" aria-label="Permalink to &quot;Behavior and limits&quot;">​</a></h2><p>HTTP GET runs in the browser with a 15-second timeout, without Studio credentials or a server proxy. CORS and mixed-content rules apply. The navigation PIN is an interface barrier stored in the project, not authorization. Browser/network failure may prevent hold-value restoration; critical devices need a HA-side timeout.</p><p>Studio uses HA entities and project pages. Separate arbitrary ioBroker color-component bindings and every Inventwo clock detail are not reproduced; exact pixel parity is not claimed. The overall shell remains DE/EN. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/universal-0.1.295.md" target="_blank" rel="noreferrer">Detailed DE/EN/FR guide</a>.</p>',12)])])}const v=a(o,[["render",n]]);export{h as __pageData,v as default};
